/**
 * Loader for the static word-vector lexicon
 * (src/assets/semantic-vectors.json, generated by scripts/build-lexicon.ts).
 *
 * The file is loaded as a RUNTIME ASSET on every platform — it is never
 * imported into a JS bundle, so the renderer / headless / capacitor
 * size-limit budgets are untouched. The read is the platform's (the webviews
 * fetch it from the webDir, the CLI single binary from the embedded SEA
 * asset, everything else from the committed src/assets copy).
 *
 * Any failure resolves to null (cached), so the caller falls back to
 * lexical-only matching — a missing or unreadable asset is a no-op, never a
 * crash.
 */

import { platform } from '../../platform/port';

import type { RawLexicon } from '../../types/semantic';

const ASSET_NAME = 'semantic-vectors.json';

// undefined = not attempted yet, null = attempted and unavailable, object = loaded
let cached: RawLexicon | null | undefined;
let inflight: Promise<RawLexicon | null> | null = null;

/**
 * Load and cache the parsed lexicon asset. Concurrent callers share one
 * in-flight load. Returns the parsed object, or null when unavailable.
 *
 * @returns the parsed JSON, unchecked (buildTable validates it)
 */
const loadLexiconAsset = async (): Promise<RawLexicon | null> => {
    if (cached !== undefined) return cached;
    if (!inflight) {
        inflight = (async () => {
            try {
                cached = (await platform().assets.readJson(ASSET_NAME)) as RawLexicon;
            } catch {
                cached = null;
            }
            return cached;
        })();
    }
    return inflight;
};

// Test-only: clear the memoized asset so a test can swap the underlying source.
const __resetForTests = () => {
    cached = undefined;
    inflight = null;
};

export { loadLexiconAsset, ASSET_NAME, __resetForTests };
